<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$user=require_permission('finance.manage');\App\Core\Tenant::enforceActive((int)$user['tenant_id']);$t=(int)$user['tenant_id'];$sqlP="SELECT id,name,cpf,primary_professional_id FROM patients WHERE tenant_id=:t AND status='active'";$pp=['t'=>$t];if(in_array($user['role_slug'],['psychologist','supervised'],true)){$sqlP.=' AND primary_professional_id=:u';$pp['u']=$user['id'];}$sqlP.=' ORDER BY name';$st=db()->prepare($sqlP);$st->execute($pp);$patients=$st->fetchAll();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=$_POST['type']??'income';$amount=(float)str_replace(',','.',$_POST['amount']??'0');$desc=trim($_POST['description']??'');$pid=(int)($_POST['patient_id']??0);if(!in_array($type,['income','expense'],true)||$amount<=0||$desc==='')$error='Revise tipo, descrição e valor.';else{$payer='';$professional=null;$validPid=$pid===0;foreach($patients as $p)if((int)$p['id']===$pid){$validPid=true;$payer=$p['cpf']??'';$professional=$p['primary_professional_id']??null;}if(!$validPid){$error='Paciente inválido para seu perfil.';}if(!$error)$st=db()->prepare("INSERT INTO financial_transactions(tenant_id,patient_id,professional_id,created_by,type,category,description,amount,due_date,status,payer_document,created_at,updated_at)VALUES(:t,:p,:prof,:u,:type,:cat,:d,:a,:due,:status,:doc,NOW(),NOW())");$status=$_POST['status']??'pending';if(!in_array($status,['pending','paid','courtesy'],true))$status='pending';if(!$error){$st->execute(['t'=>$t,'p'=>$pid?:null,'prof'=>$professional?:null,'u'=>$user['id'],'type'=>$type,'cat'=>trim($_POST['category']??'Sessões')?:'Geral','d'=>$desc,'a'=>$amount,'due'=>($_POST['due_date']??'')?:date('Y-m-d'),'status'=>$status,'doc'=>$payer?:null]);$id=(int)db()->lastInsertId();if($status==='paid')db()->prepare("UPDATE financial_transactions SET paid_at=NOW() WHERE id=:id AND tenant_id=:t")->execute(['id'=>$id,'t'=>$t]);audit('finance.transaction_create','financial_transaction',$id,['type'=>$type,'amount'=>$amount]);flash('success','Lançamento salvo.');redirect('finance/index.php');}}}
layout('Novo lançamento',function()use($patients,$error){?><div class="page-head"><div><span class="eyebrow">Financeiro</span><h1>Novo lançamento</h1></div></div><form method="post" class="card form-grid"><?=csrf_field()?><?php if($error):?><div class="error-box"><?=e($error)?></div><?php endif?><div class="form-row"><div class="field"><label>Tipo</label><select name="type"><option value="income">Receita</option><option value="expense">Despesa</option></select></div><div class="field"><label>Status</label><select name="status"><option value="pending">Pendente</option><option value="paid">Pago</option><option value="courtesy">Cortesia</option></select></div></div><div class="field"><label>Paciente (opcional)</label><select name="patient_id"><option value="">Sem vínculo</option><?php foreach($patients as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach?></select></div><div class="form-row"><div class="field"><label>Categoria</label><input name="category" value="Sessões"></div><div class="field"><label>Vencimento</label><input type="date" name="due_date" value="<?=e(date('Y-m-d'))?>"></div></div><div class="field"><label>Descrição</label><input name="description" required></div><div class="field"><label>Valor</label><input name="amount" inputmode="decimal" required placeholder="150,00"></div><button class="button">Salvar lançamento</button></form><?php },['active'=>'finance']);
